                Description = "Covers limits, derivatives, and integrals of single-variable functions. Applications include rates of change, optimization problems, and area computations. A strong algebra background is recommended.",
                Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Location = "Science Center 101",
                DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = true,
                Instructor = new() { Id = 4, Name = "Dr. James Whitfield", Title = "Professor", Bio = "Dr. Whitfield has taught calculus for over 20 years and received the Distinguished Teaching Award three times. His research focuses on mathematical analysis and differential equations. He is known for making complex topics accessible.", Email = "jwhitfield@university.edu" }
            },
            new()
