                Description = "Study of vector spaces, matrices, linear transformations, eigenvalues, and eigenvectors. Applications in computer graphics, data science, and engineering are explored throughout the course.",
                Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", Location = "Science Center 203",
                DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = false,
                Instructor = new() { Id = 5, Name = "Dr. Emily Nakamura", Title = "Associate Professor", Bio = "Dr. Nakamura's research bridges pure mathematics and machine learning applications. She has developed innovative visual approaches to teaching linear algebra. She completed her postdoc at the Institute for Advanced Study.", Email = "enakamura@university.edu" }
            },
            new()
            {
                Id = 6, Code = "MATH 320", Title = "Probability and Statistics",
                Description = "Introduction to probability theory, random variables, distributions, hypothesis testing, and regression analysis. Emphasizes real-world applications in science, business, and public policy.",
                Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", Location = "Science Center 105",
                DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = false,
                Instructor = new() { Id = 4, Name = "Dr. James Whitfield", Title = "Professor", Bio = "Dr. Whitfield has taught calculus for over 20 years and received the Distinguished Teaching Award three times. His research focuses on mathematical analysis and differential equations. He is known for making complex topics accessible.", Email = "jwhitfield@university.edu" }
