            },
            new()
            {
                Id = 13, Code = "HIST 101", Title = "World History to 1500",
                Description = "Survey of world civilizations from prehistory through the late medieval period. Topics include the rise of agriculture, ancient empires, trade networks, and the spread of major religions.",
                Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Location = "Liberal Arts 120",
                DepartmentId = 5, DepartmentName = "History", IsFeatured = false,
                Instructor = new() { Id = 11, Name = "Dr. Catherine Torres", Title = "Professor", Bio = "Dr. Torres is a specialist in ancient and medieval world history. She has conducted archaeological research in the Mediterranean and Central America. Her teaching emphasizes primary source analysis.", Email = "ctorres@university.edu" }
            },
            new()
            {
                Id = 14, Code = "HIST 225", Title = "The American Civil War",
                Description = "In-depth examination of the causes, course, and consequences of the American Civil War. Analyzes military strategy, political leadership, slavery, emancipation, and Reconstruction.",
                Credits = 3, Schedule = "Tue/Thu 3:30–4:50 PM", Location = "Liberal Arts 205",
                DepartmentId = 5, DepartmentName = "History", IsFeatured = false,
                Instructor = new() { Id = 12, Name = "Dr. Thomas Grant", Title = "Associate Professor", Bio = "Dr. Grant is an authority on 19th-century American history and the Civil War era. He has authored three books on military history and political leadership. He frequently contributes to historical documentaries.", Email = "tgrant@university.edu" }
            },
            new()
            {
                Id = 15, Code = "HIST 310", Title = "Modern European History",
                Description = "Covers European history from the French Revolution to the present, including industrialization, nationalism, world wars, the Cold War, and European integration.",
                Credits = 3, Schedule = "Mon/Wed 4:00–5:20 PM", Location = "Liberal Arts 310",
                DepartmentId = 5, DepartmentName = "History", IsFeatured = false,
                Instructor = new() { Id = 11, Name = "Dr. Catherine Torres", Title = "Professor", Bio = "Dr. Torres is a specialist in ancient and medieval world history. She has conducted archaeological research in the Mediterranean and Central America. Her teaching emphasizes primary source analysis.", Email = "ctorres@university.edu" }
            }
        };
    }

    public Task<IReadOnlyList<Department>> GetDepartmentsAsync()
    {
        return Task.FromResult<IReadOnlyList<Department>>(_departments.AsReadOnly());
    }

    public Task<IReadOnlyList<Course>> GetCoursesAsync(string? searchTerm = null, int? departmentId = null)
    {
        IEnumerable<Course> results = _courses;

        if (departmentId.HasValue)
        {
            results = results.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            results = results.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return Task.FromResult<IReadOnlyList<Course>>(results.ToList().AsReadOnly());
    }

    public Task<IReadOnlyList<Course>> GetFeaturedCoursesAsync()
    {
        var featured = _courses.Where(c => c.IsFeatured).ToList().AsReadOnly();
        return Task.FromResult<IReadOnlyList<Course>>(featured);
    }

    public Task<Course?> GetCourseByIdAsync(int id)
    {
        var course = _courses.FirstOrDefault(c => c.Id == id);
        return Task.FromResult(course);
    }

    public Task<bool> SubmitEnrollmentRequestAsync(EnrollmentRequest request)
    {
        Console.WriteLine($"Enrollment request received: {request.StudentName} ({request.StudentId}) for course ID {request.CourseId}");
        return Task.FromResult(true);
    }
}

