@page "/courses"
@inject ICatalogService CatalogService
@inject NavigationManager Navigation

<PageTitle>Course Catalog</PageTitle>

<h1 class="mb-4">Course Catalog</h1>

<CourseFilters SearchTerm="@_searchTerm"
              SearchTermChanged="OnSearchTermChanged"
              SelectedDepartmentId="@_selectedDepartmentId"
              SelectedDepartmentIdChanged="OnDepartmentChanged"
              Departments="@_departments" />

@if (_courses is null)
{
    <p><em>Loading courses...</em></p>
}
else if (_courses.Count == 0)
{
    <div class="alert alert-info">No courses found matching your criteria.</div>
}
else
{
    <div class="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-4">
        @foreach (var course in _courses)
        {
            <div class="col">
                <CourseCard Course="@course" />
            </div>
        }
    </div>
}

@code {
    [SupplyParameterFromQuery]
    public int? DepartmentId { get; set; }

    private IReadOnlyList<Course>? _courses;
    private IReadOnlyList<Department> _departments = [];
    private string _searchTerm = string.Empty;
    private int? _selectedDepartmentId;

    protected override async Task OnInitializedAsync()
    {
        _selectedDepartmentId = DepartmentId;
        _departments = await CatalogService.GetDepartmentsAsync();
        await LoadCoursesAsync();
    }

    private async Task OnSearchTermChanged(string searchTerm)
    {
        _searchTerm = searchTerm;
        await LoadCoursesAsync();
    }

    private async Task OnDepartmentChanged(int? departmentId)
    {
        _selectedDepartmentId = departmentId;
        await LoadCoursesAsync();
    }

    private async Task LoadCoursesAsync()
    {
        _courses = await CatalogService.GetCoursesAsync(_searchTerm, _selectedDepartmentId);
    }
}

@page "/courses/{Id:int}"
@inject ICatalogService CatalogService

<PageTitle>@(_course?.Title ?? "Course Detail")</PageTitle>

@if (_course is null)
{
    <div class="alert alert-warning">Course not found.</div>
    <a href="/courses" class="btn btn-secondary">Back to Catalog</a>
}
else
{
    <nav aria-label="breadcrumb" class="mb-3">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/courses">Catalog</a></li>
            <li class="breadcrumb-item active" aria-current="page">@_course.Code</li>
        </ol>
    </nav>

    <h1>@_course.Code — @_course.Title</h1>
    <p class="text-muted">@_course.DepartmentName</p>

    <p class="lead">@_course.Description</p>

    <div class="row g-4 mt-3">
        <div class="col-md-6">
            <CourseScheduleInfo Course="@_course" />
        </div>
        <div class="col-md-6">
            <InstructorBioCard Instructor="@_course.Instructor" />
        </div>
    </div>

    <div class="mt-4">
        <a href="/enroll?CourseId=@_course.Id" class="btn btn-primary me-2">Enroll in This Course</a>
        <a href="/courses" class="btn btn-outline-secondary">Back to Catalog</a>
    </div>
}

@code {
    [Parameter] public int Id { get; set; }

    private Course? _course;

    protected override async Task OnInitializedAsync()
    {
        _course = await CatalogService.GetCourseByIdAsync(Id);
    }
}

@page "/enroll"
@inject ICatalogService CatalogService

<PageTitle>Enrollment Request</PageTitle>

<h1 class="mb-4">Enrollment Request</h1>

@if (_submitted)
{
    <div class="alert alert-success">
        <h4>Enrollment Request Submitted!</h4>
        <p>Thank you, <strong>@_model.StudentName</strong>. Your enrollment request for the selected course has been received.</p>
        <a href="/courses" class="btn btn-outline-primary mt-2">Browse More Courses</a>
    </div>
}
else
{
    <EditForm Model="@_model" OnValidSubmit="HandleSubmit" FormName="enroll">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger mb-3" />

        <div class="mb-3">
            <label for="studentName" class="form-label">Student Name</label>
            <InputText id="studentName" class="form-control" @bind-Value="_model.StudentName" />
            <ValidationMessage For="() => _model.StudentName" />
        </div>

        <div class="mb-3">
            <label for="studentId" class="form-label">Student ID</label>
            <InputText id="studentId" class="form-control" @bind-Value="_model.StudentId" placeholder="e.g., CS123456" />
            <ValidationMessage For="() => _model.StudentId" />
        </div>

        <div class="mb-3">
            <label for="courseId" class="form-label">Course</label>
            <InputSelect id="courseId" class="form-select" @bind-Value="_model.CourseId">
                <option value="0">-- Select a course --</option>
                @if (_courses is not null)
                {
                    @foreach (var course in _courses)
                    {
                        <option value="@course.Id">@course.Code — @course.Title</option>
                    }
                }
            </InputSelect>
            <ValidationMessage For="() => _model.CourseId" />
        </div>

        <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
    </EditForm>
}

@code {
    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    private EnrollmentRequest _model = new();
    private IReadOnlyList<Course>? _courses;
    private bool _submitted;

    protected override async Task OnInitializedAsync()
    {
        _courses = await CatalogService.GetCoursesAsync();
        if (CourseId.HasValue)
        {
            _model.CourseId = CourseId.Value;
        }
    }

    private async Task HandleSubmit()
    {
        var result = await CatalogService.SubmitEnrollmentRequestAsync(_model);
        if (result)
        {
            _submitted = true;
        }
    }
}

