     private IReadOnlyList<Course>? _courses;
     private IReadOnlyList<Department> _departments = [];
     private string _searchTerm = string.Empty;
     private int? _selectedDepartmentId;

     protected override async Task OnInitializedAsync()
     {
         _selectedDepartmentId = DepartmentId;
         _departments = await CatalogService.GetDepartmentsAsync();
         await LoadCoursesAsync();
     }

     private async Task OnSearchTermChanged(string searchTerm)
     {
         _searchTerm = searchTerm;
         await LoadCoursesAsync();
     }

     private async Task OnDepartmentChanged(int? departmentId)
     {
         _selectedDepartmentId = departmentId;
         await LoadCoursesAsync();
     }

     private async Task LoadCoursesAsync()
     {
         _courses = await CatalogService.GetCoursesAsync(_searchTerm, _selectedDepartmentId);
     }
 }

