 @page "/courses/{Id:int}"
 @inject ICatalogService CatalogService

 <PageTitle>@(_course?.Title ?? "Course Detail")</PageTitle>

 @if (_course is null)
 {
     <div class="alert alert-warning">Course not found.</div>
     <a href="/courses" class="btn btn-secondary">Back to Catalog</a>
 }
 else
 {
     <nav aria-label="breadcrumb" class="mb-3">
         <ol class="breadcrumb">
             <li class="breadcrumb-item"><a href="/courses">Catalog</a></li>
             <li class="breadcrumb-item active" aria-current="page">@_course.Code</li>
         </ol>
     </nav>

     <h1>@_course.Code — @_course.Title</h1>
     <p class="text-muted">@_course.DepartmentName</p>

     <p class="lead">@_course.Description</p>

     <div class="row g-4 mt-3">
         <div class="col-md-6">
             <CourseScheduleInfo Course="@_course" />
         </div>
         <div class="col-md-6">
             <InstructorBioCard Instructor="@_course.Instructor" />
         </div>
     </div>

     <div class="mt-4">
         <a href="/enroll?CourseId=@_course.Id" class="btn btn-primary me-2">Enroll in This Course</a>
         <a href="/courses" class="btn btn-outline-secondary">Back to Catalog</a>
     </div>
 }

